document.documentElement.classList.remove('no-js');
const menu=document.querySelector('.menu-toggle');const nav=document.querySelector('.topnav');if(menu&&nav){menu.addEventListener('click',()=>{const open=nav.classList.toggle('is-open');menu.setAttribute('aria-expanded',String(open));menu.querySelector('span').textContent=open?'−':'＋'});nav.addEventListener('click',e=>{if(e.target.closest('a')){nav.classList.remove('is-open');menu.setAttribute('aria-expanded','false');menu.querySelector('span').textContent='＋'}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('is-open')){nav.classList.remove('is-open');menu.setAttribute('aria-expanded','false');menu.focus()}})}const motion=document.querySelector('.motion-toggle');if(motion)motion.addEventListener('click',()=>{const paused=document.body.classList.toggle('motion-paused');motion.setAttribute('aria-pressed',String(paused));motion.innerHTML=paused?'Bewegung fortsetzen <span aria-hidden="true">▷</span>':'Bewegung pausieren <span aria-hidden="true">Ⅱ</span>'});
